diff --git a/.mulch/expertise/gofib.jsonl b/.mulch/expertise/gofib.jsonl
index 0bdfd61..a117580 100644
--- a/.mulch/expertise/gofib.jsonl
+++ b/.mulch/expertise/gofib.jsonl
@@ -1,2 +1,3 @@
 {"type":"pattern","classification":"tactical","recorded_at":"2026-08-22T17:10:28.450Z","evidence":{"seeds":"fabro-759d","commit":"802b69be5b96ee07d2af8abf553e0f7ff5205750"},"name":"thin-main-runnable-core","description":"gofib CLI testability: keep main() as a thin flag.Parse + error-exit shim and put all output logic in run(w io.Writer, count int) error, so tests exercise CLI behavior (counts, formats, invalid -n values) via bytes.Buffer instead of os/exec subprocesses. New flags should validate in run and surface errors through main's stderr+exit-1 path.","files":[".mulch/mulch.config.yaml","fib_test.go","main.go"],"id":"mx-d4cf38"}
 {"type":"failure","classification":"tactical","recorded_at":"2026-08-22T18:08:57.202Z","evidence":{"commit":"423d296789e3a8c6f97e29e6f03f4fe41fb56356"},"description":"A previous implementer pass left a compiled 'gofib' binary in the worktree root (gitignored, so the gate stayed green). Hard rule: build smoke checks must not leave binaries behind — use 'go run .' (builds to cache) or build into a temp dir outside the worktree, and remove any stray binary before finishing the pass.","resolution":"Binary removed with 'rm -f gofib'; smoke checks now use 'go run .' which builds into the Go cache and never touches the worktree.","id":"mx-a58327"}
+{"type":"pattern","classification":"tactical","recorded_at":"2026-08-23T15:06:00.482Z","evidence":{"commit":"b60d2adb8b9e0ce62b62dc0924d0576f72edb684"},"name":"run-seam-flag-precedence","description":"Output-mode precedence in the gofib CLI lives in the run() seam as early-return branches ordered by precedence (version check before the count<1 validation), so every flag combination — including precedence-over-validation cases like -version -n 0 — is unit-testable through run() parameters without process execution. Adding a new output mode means adding one bool parameter, threading 'false' through existing call sites, and putting its branch at its precedence position.","files":["fib_test.go","main.go"],"id":"mx-bd4a50"}
diff --git a/fib_test.go b/fib_test.go
index 1659124..176645c 100644
--- a/fib_test.go
+++ b/fib_test.go
@@ -54,7 +54,7 @@ func TestRun(t *testing.T) {
 	for _, tt := range tests {
 		t.Run(tt.name, func(t *testing.T) {
 			var buf bytes.Buffer
-			if err := run(&buf, tt.n, false, false); err != nil {
+			if err := run(&buf, tt.n, false, false, false); err != nil {
 				t.Fatalf("run(%d) returned error: %v", tt.n, err)
 			}
 			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
@@ -95,7 +95,7 @@ func TestRunJSON(t *testing.T) {
 	for _, tt := range tests {
 		t.Run(tt.name, func(t *testing.T) {
 			var buf bytes.Buffer
-			if err := run(&buf, tt.n, true, false); err != nil {
+			if err := run(&buf, tt.n, true, false, false); err != nil {
 				t.Fatalf("run(%d, json) returned error: %v", tt.n, err)
 			}
 			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
@@ -143,7 +143,7 @@ func TestRunPretty(t *testing.T) {
 	} {
 		t.Run(tt.name, func(t *testing.T) {
 			var buf bytes.Buffer
-			if err := run(&buf, tt.n, false, true); err != nil {
+			if err := run(&buf, tt.n, false, true, false); err != nil {
 				t.Fatalf("run(%d, pretty) returned error: %v", tt.n, err)
 			}
 			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
@@ -163,7 +163,7 @@ func TestRunPretty(t *testing.T) {
 	// index right-aligned to len("100"), value to len(Fib(100)).
 	t.Run("pretty default prints 100 aligned numbers", func(t *testing.T) {
 		var buf bytes.Buffer
-		if err := run(&buf, defaultCount, false, true); err != nil {
+		if err := run(&buf, defaultCount, false, true, false); err != nil {
 			t.Fatalf("run(default, pretty) returned error: %v", err)
 		}
 		lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
@@ -181,10 +181,10 @@ func TestRunPrettyJSON(t *testing.T) {
 	// -pretty only affects text mode: with -json the output must be
 	// identical, line for line.
 	var jsonOnly, prettyJSON bytes.Buffer
-	if err := run(&jsonOnly, 3, true, false); err != nil {
+	if err := run(&jsonOnly, 3, true, false, false); err != nil {
 		t.Fatalf("run(3, json) returned error: %v", err)
 	}
-	if err := run(&prettyJSON, 3, true, true); err != nil {
+	if err := run(&prettyJSON, 3, true, true, false); err != nil {
 		t.Fatalf("run(3, json, pretty) returned error: %v", err)
 	}
 	if prettyJSON.String() != jsonOnly.String() {
@@ -205,7 +205,7 @@ func TestRunRejectsInvalidCount(t *testing.T) {
 	}{{"text", false}, {"json", true}} {
 		for _, n := range []int{0, -5} {
 			var buf bytes.Buffer
-			err := run(&buf, n, mode.asJSON, false)
+			err := run(&buf, n, mode.asJSON, false, false)
 			if err == nil {
 				t.Fatalf("run(%d, %s) succeeded, want error", n, mode.name)
 			}
@@ -218,3 +218,38 @@ func TestRunRejectsInvalidCount(t *testing.T) {
 		}
 	}
 }
+
+func TestRunVersion(t *testing.T) {
+	// -version takes precedence over every other mode: whatever the
+	// other flags say, the output is the single line "gofib <Version>"
+	// and the call succeeds (the exit-0 path). This includes the
+	// count<1 validation, which -version outranks.
+	for _, tt := range []struct {
+		name   string
+		count  int
+		asJSON bool
+		pretty bool
+	}{
+		{"version alone", defaultCount, false, false},
+		{"version with -json -n 5", 5, true, false},
+		{"version with -pretty", 10, false, true},
+		// Spec: precedence over ALL modes includes the count validation:
+		// -version -n 0 must still print only the version line, exit 0.
+		{"version with -n 0", 0, false, false},
+		{"version with -json -n 0", 0, true, false},
+	} {
+		t.Run(tt.name, func(t *testing.T) {
+			var buf bytes.Buffer
+			if err := run(&buf, tt.count, tt.asJSON, tt.pretty, true); err != nil {
+				t.Fatalf("run(version) returned error: %v", err)
+			}
+			want := "gofib " + Version + "\n"
+			if got := buf.String(); got != want {
+				t.Errorf("run(version) output = %q, want exactly %q", got, want)
+			}
+			if n := strings.Count(buf.String(), "\n"); n != 1 {
+				t.Errorf("run(version) printed %d lines, want exactly 1", n)
+			}
+		})
+	}
+}
diff --git a/main.go b/main.go
index 47c896f..c2e16c4 100644
--- a/main.go
+++ b/main.go
@@ -2,7 +2,8 @@
 // the index: "1: 1", "2: 1", "3: 2", ... By default it prints the first
 // 100; the -n flag changes how many are printed, -json switches to
 // JSON Lines output, and -pretty aligns the text columns (it has no
-// effect with -json).
+// effect with -json). The -version flag prints the gofib version and
+// exits, taking precedence over all other output modes.
 package main

 import (
@@ -15,6 +16,9 @@ import (
 	"strconv"
 )

+// Version is the gofib release version printed by -version.
+const Version = "1.3.0"
+
 // defaultCount is how many numbers gofib prints when -n is omitted.
 const defaultCount = 100

@@ -39,9 +43,15 @@ func Fib(n int) *big.Int {
 // the index to the width of the largest index printed and the value to
 // the width of the largest value printed, separated by ": ". In JSON
 // mode each line is one JSON object {"index": <int>, "fib": "<value>"}
-// (JSON Lines) and pretty has no effect. It returns an error when
-// count < 1.
-func run(w io.Writer, count int, asJSON, pretty bool) error {
+// (JSON Lines) and pretty has no effect. With version it prints only the
+// single line "gofib <Version>" — this takes precedence over every other
+// mode, including the count validation. It returns an error when
+// count < 1 (and version is not set).
+func run(w io.Writer, count int, asJSON, pretty, version bool) error {
+	if version {
+		_, err := fmt.Fprintln(w, "gofib", Version)
+		return err
+	}
 	if count < 1 {
 		return fmt.Errorf("invalid value %d for flag -n: must be >= 1", count)
 	}
@@ -71,8 +81,9 @@ func main() {
 	n := flag.Int("n", defaultCount, "how many Fibonacci numbers to print (must be >= 1; default 100)")
 	asJSON := flag.Bool("json", false, "emit JSON Lines instead of text: one {\"index\": i, \"fib\": \"value\"} object per number")
 	pretty := flag.Bool("pretty", false, "align text output into two right-aligned columns sized to the largest index and value (no effect with -json)")
+	version := flag.Bool("version", false, "print the gofib version and exit (takes precedence over all other output modes)")
 	flag.Parse()
-	if err := run(os.Stdout, *n, *asJSON, *pretty); err != nil {
+	if err := run(os.Stdout, *n, *asJSON, *pretty, *version); err != nil {
 		fmt.Fprintln(os.Stderr, err)
 		os.Exit(1)
 	}

